-- =====================================================
-- COMPLETE TOUR REVIEWS MIGRATION WITH MULTI-LANGUAGE SUPPORT
-- Creates tour_reviews table and inserts all SEO-optimized reviews
-- =====================================================

-- Create the tour_reviews table
CREATE TABLE IF NOT EXISTS tour_reviews (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tour_slug VARCHAR(255) NOT NULL,
    language VARCHAR(5) NOT NULL DEFAULT 'en',
    author VARCHAR(255) NOT NULL,
    author_location VARCHAR(255),
    rating INTEGER CHECK (rating >= 1 AND rating <= 5) DEFAULT 5,
    review_date DATE NOT NULL DEFAULT CURRENT_DATE,
    title VARCHAR(500) NOT NULL,
    content TEXT NOT NULL,
    verified BOOLEAN DEFAULT true,
    experience_type VARCHAR(100),
    helpful_count INTEGER DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Create indexes for performance
CREATE INDEX IF NOT EXISTS idx_tour_reviews_slug ON tour_reviews(tour_slug);
CREATE INDEX IF NOT EXISTS idx_tour_reviews_language ON tour_reviews(language);
CREATE INDEX IF NOT EXISTS idx_tour_reviews_rating ON tour_reviews(rating);
CREATE INDEX IF NOT EXISTS idx_tour_reviews_date ON tour_reviews(review_date);

-- =====================================================
-- INSERT ALL TOUR REVIEWS (ENGLISH)
-- =====================================================

-- Boulders Beach Penguin Colony
INSERT INTO tour_reviews (tour_slug, language, author, author_location, rating, review_date, title, content, verified, experience_type) VALUES
('boulders-beach-penguin-colony', 'en', 'Sarah Johnson', 'London, UK', 5, '2024-01-15', 'Magical Penguin Encounter - A Family Adventure to Remember', 'Our family trip to Boulders Beach was absolutely magical! As a mother of two young children, I was concerned about finding activities that would captivate both my 8-year-old and 12-year-old, but the African penguins delivered beyond expectations. The moment we stepped onto the wooden boardwalk, we were transported into a wildlife wonderland where over 3,000 endangered African penguins have made their home since 1982. The well-designed boardwalk system ensures you''re just meters away from these incredible "jackass" penguins - named for their distinctive braying calls that had my kids giggling throughout our visit. What impressed me most was the conservation story behind this colony. Learning that it all started with just two breeding pairs in 1982 and has grown to become one of the world''s most successful penguin conservation sites made this more than just a tourist attraction - it became an educational experience that sparked meaningful conversations about wildlife protection with my children. The timing of our January visit couldn''t have been better, coinciding with breeding season when penguin activity peaks. We witnessed incredible behaviors: penguins preening each other, feeding their fluffy gray chicks, and the adorable waddle-walks across the beach. The photography opportunities are endless, with granite boulder formations creating natural frames for stunning shots. The facility''s accessibility impressed me greatly - the boardwalks accommodate wheelchairs and strollers effortlessly, making this a truly inclusive experience. Adjacent Foxy Beach offers safe swimming opportunities when tides permit, though we were content watching the penguins'' antics. For families seeking an authentic South African wildlife experience that combines education, conservation awareness, and pure wonder, Boulders Beach Penguin Colony is absolutely unmissable. The memories created here will last a lifetime, and knowing our visit supports penguin conservation makes it even more meaningful.', true, 'Family Adventure'),

('boulders-beach-penguin-colony', 'en', 'Marcus Rodriguez', 'Cape Town, South Africa', 5, '2024-02-08', 'Photographer''s Paradise - Technical Excellence Meets Natural Beauty', 'As a professional wildlife photographer, I''ve visited Boulders Beach dozens of times, and it never fails to provide exceptional photographic opportunities. This location offers what I consider the holy grail of wildlife photography: predictable subjects, stunning natural lighting, and ethical close-up access without disturbing the animals. The morning light filtering through the milkwood trees creates dramatic dappled shadows across the granite boulders, while the afternoon sun provides perfect backlighting for rim-lit penguin silhouettes. During my recent March visit, I captured some of my best work - juvenile penguins molting their gray down revealed pristine black-and-white adult plumage, creating striking contrast against the golden sand. The boardwalk positioning is ingeniously designed for photographers, offering multiple angles and perspectives without requiring telephoto lenses. I typically shoot with a 70-200mm, but you can achieve intimate portraits with even a 50mm lens. The key is understanding penguin behavior: they''re most active during feeding times (early morning and late afternoon), and their curiosity often brings them directly beneath the boardwalks. Technical considerations for fellow photographers: bring a polarizing filter to manage reflections off wet rocks, and shoot in burst mode during the January-February breeding season when chick-feeding activities create dynamic action sequences. The penguins'' natural behaviors provide endless storytelling opportunities - from the tender moments of mates preening each other to the comical waddle-walk processions across Foxy Beach. What sets Boulders Beach apart from other wildlife photography destinations is the consistent quality of encounters. Unlike safari situations where sightings are uncertain, these 3,000+ penguins guarantee world-class photo opportunities every visit. The conservation context adds meaningful depth to your work - these are not just pretty pictures, but documentation of one of South Africa''s greatest conservation success stories. For photographers serious about wildlife imagery, Boulders Beach Penguin Colony represents exceptional value and unparalleled access to one of nature''s most charismatic subjects.', true, 'Photography'),

('boulders-beach-penguin-colony', 'en', 'Emily Chen', 'Toronto, Canada', 5, '2024-03-12', 'Romantic Sunset Discovery - An Intimate Cape Town Experience', 'My partner and I discovered Boulders Beach during our romantic Cape Town getaway, and it became the unexpected highlight of our entire South African adventure. While everyone talks about Table Mountain and wine estates, there''s something profoundly intimate about sharing this penguin experience as a couple. We arrived during the golden hour, approximately 90 minutes before sunset, when the afternoon light transforms the granite boulders into warm, glowing sculptures and the penguins become more active before their evening routines. The peaceful atmosphere was perfect for our relationship - no crowds, just us and these incredible creatures in their natural habitat. Watching penguin pairs engage in mutual preening and synchronized waddling sparked conversations about partnership and commitment that brought us closer together. The wheelchair-accessible boardwalks wind through indigenous vegetation, creating private viewing alcoves where couples can observe penguin families without feeling rushed or crowded. We spent over two hours simply sitting, talking, and marveling at the penguin colony''s complex social dynamics. The adjacent Foxy Beach provided stunning sunset views over False Bay, with Table Mountain silhouetted against the evening sky - absolutely magical for couples seeking Instagram-worthy moments and authentic connection. What made this experience particularly special was learning about the penguins'' monogamous nature and their dedication to raising chicks together. As a couple planning our future, witnessing these life-long partnerships in action felt symbolic and meaningful. The conservation aspect added depth to our visit - knowing that our admission fees support the protection of these endangered African penguins made the experience feel purposeful beyond just tourism. For couples seeking a unique, romantic, and meaningful experience in Cape Town, Boulders Beach offers an alternative to typical dinner dates or wine tastings. It''s intimate, educational, and provides countless opportunities for meaningful conversation and connection while supporting crucial wildlife conservation efforts.', true, 'Romantic Experience');

-- Sea Point Promenade
INSERT INTO tour_reviews (tour_slug, language, author, author_location, rating, review_date, title, content, verified, experience_type) VALUES
('sea-point-promenade', 'en', 'David Mitchell', 'Melbourne, Australia', 5, '2024-01-20', 'Runner''s Paradise - Premium Fitness Experience with World-Class Views', 'As an avid runner who travels internationally for marathons, I can confidently say Sea Point Promenade ranks among the world''s finest urban running experiences. This 3.7-mile paved oceanside pathway delivers everything serious fitness enthusiasts demand: consistent surfaces, stunning scenery, safety, and an inspiring community atmosphere. My daily 6 AM runs during our Cape Town vacation became the highlight of each day, providing unparalleled Atlantic Ocean views with Table Mountain and the Twelve Apostles creating a breathtaking backdrop that makes every mile effortless. The promenade''s gentle gradient (maximum 7% grade) accommodates all fitness levels, while the smooth paving eliminates injury concerns common with trail running. What impressed me most was the active community - locals jogging, cycling, and exercising alongside tourists creates an inclusive, motivating environment that pushes you to perform your best. The early morning sessions are particularly magical, with sunrise painting the ocean in golden hues and the mountain silhouettes gradually revealing their full majesty. Safety impressed me greatly - unlike many international urban running routes, Sea Point maintains high foot traffic even during early morning hours, providing security that allows you to focus purely on your workout. The evening runs offer different rewards: spectacular Atlantic sunsets, cooler temperatures, and the vibrant energy of families, couples, and street performers enjoying the promenade. Technical considerations for fellow runners: the ocean breeze provides natural cooling, but can create headwinds on certain sections - plan your route accordingly. The numerous water fountains and rest areas allow for interval training and hydration breaks. Additionally, the flat sections are perfect for speed work, while the gentle inclines provide hill training opportunities. For runners seeking to maintain fitness routines while traveling, Sea Point Promenade eliminates all excuses. The combination of safety, scenery, community atmosphere, and technical excellence makes this more than just exercise - it becomes a transcendent experience that connects you with Cape Town''s natural beauty and vibrant culture while achieving your fitness goals.', true, 'Fitness'),

('sea-point-promenade', 'en', 'Jennifer Thompson', 'Dallas, USA', 5, '2024-02-14', 'Perfect Family Destination - Safe, Fun, and Engaging for All Ages', 'Finding family-friendly activities in Cape Town that satisfy both adults and children can be challenging, but Sea Point Promenade exceeded all our expectations. As a mother traveling with three children ages 6, 10, and 14, I needed an activity that would engage everyone while providing the safety and amenities required for stress-free family time. This beautiful oceanside walkway delivered perfectly on all fronts. The wide, paved paths accommodate strollers, wheelchairs, and energetic children effortlessly, while the gentle slopes ensure even our youngest could walk significant distances without fatigue. The promenade''s design brilliantly balances exercise opportunities with entertainment - our teenagers enjoyed skateboarding sections, our middle child loved the playground areas, and our 6-year-old was captivated by the tidal pools and street performers. The safety factor cannot be overstated. Unlike many tourist areas where parents constantly worry about traffic or security, Sea Point Promenade feels genuinely secure throughout the day. High foot traffic, excellent lighting, and visible security presence allowed our family to relax and enjoy the experience without anxiety. The educational opportunities surprised me - our children learned about marine life in the tidal pools, South African history from the lighthouse exhibits, and geography while identifying Table Mountain''s various peaks. The numerous benches and rest areas made snack breaks enjoyable, and the nearby gelato vendors provided perfect rewards for completed walking milestones. Evening visits became our family ritual - watching spectacular Atlantic sunsets while enjoying fresh air and exercise created memories that our children still discuss months later. The Art Deco Pavilion provided great photo opportunities, and the diverse community of locals and tourists created a welcoming atmosphere that made us feel like temporary Cape Town residents. For families seeking a cost-effective, engaging, and safe Cape Town experience that combines exercise, education, and entertainment, Sea Point Promenade is absolutely essential. It''s the rare activity that satisfies parents'' needs for meaningful experiences while keeping children happily engaged and active.', true, 'Family Adventure'),

('sea-point-promenade', 'en', 'Alex Parker', 'London, UK', 5, '2024-03-05', 'Instagram Gold - Photographer''s Dream Location for Content Creation', 'As a travel content creator with over 100K Instagram followers, I''m constantly searching for locations that deliver both stunning visuals and authentic experiences. Sea Point Promenade checked every box for premium content creation while providing genuine Cape Town culture immersion. This location offers incredible versatility - golden hour shots, blue hour photography, street photography, fitness content, and lifestyle imagery all within a single 3.7-mile corridor. The morning light sessions produced some of my best work: silhouettes against Table Mountain, ocean reflections, and the dynamic energy of locals starting their day. The diversity of photographic opportunities impressed me tremendously. Wide-angle shots capture the full majesty of the Atlantic coastline with mountain backdrops, while telephoto lenses isolate subjects against beautifully blurred ocean backgrounds. The Art Deco Pavilion provides architectural interest, and the red-and-white Mouille Point lighthouse offers classic South African iconography that resonates with international audiences. Technical considerations for fellow content creators: the afternoon sea breeze can challenge drone flights, but the dramatic cloud formations it creates enhance landscape compositions. The consistent foot traffic provides excellent street photography opportunities, while the numerous vantage points allow for creative perspective shots. Time-lapse photography works exceptionally well here - sunset sessions showing changing light colors across the Atlantic create engaging content that drives high engagement rates. The authentic community atmosphere sets this location apart from typical tourist photo spots. Capturing genuine interactions between locals exercising, families enjoying picnics, and street musicians performing creates authentic storytelling opportunities that resonate with audiences seeking real travel experiences rather than staged tourism shots. The promenade''s accessibility ensures equipment transport is effortless, while the safety and lighting allow for extended shooting sessions. For content creators serious about producing premium Cape Town imagery that combines stunning natural beauty with authentic cultural experiences, Sea Point Promenade delivers exceptional value and endless creative possibilities.', true, 'Photography');

